import numpy as np
from math import sqrt, sin, cos, pi
atoms=[]; bonds=[]
def add(el,pos):
    atoms.append((el,np.array(pos,dtype=float))); return len(atoms)-1
def bond(a,b): bonds.append((a,b))
def norm(v): return v/np.linalg.norm(v)
def tetra_rest(u,v):
    u,v=norm(u),norm(v)
    mid=-norm(u+v)/sqrt(3); perp=norm(np.cross(u,v))*sqrt(2/3)
    return mid+perp,mid-perp
metal=add('Tc',[0,0,0]); donors=[]
for side in [-1,1]:
    ps=[]; cs=[]
    for ysign in [1,-1]:
        p=add('P',[side*1.84,ysign*1.54,0]); ps.append(p); donors.append(p); bond(metal,p)
        c=add('C',[side*3.41,ysign*.70,ysign*side*.25]); cs.append(c); bond(p,c)
        u=atoms[metal][1]-atoms[p][1];v=atoms[c][1]-atoms[p][1]
        for w in tetra_rest(u,v):
            m=add('C',atoms[p][1]+1.84*w); bond(p,m)
    bond(cs[0],cs[1])
ss=[]
for side in [1,-1]:
    s=add('S',[0,0,side*2.34]); ss.append(s); bond(metal,s)
    c=add('C',[side*1.74,0,side*2.99]); bond(s,c)
# Explicit carbon hydrogens, with tetrahedral angles.
for i,(el,pos) in list(enumerate(atoms)):
    if el!='C': continue
    ns=[b if a==i else a for a,b in bonds if a==i or b==i]
    if len(ns)==1:
        u=norm(atoms[ns[0]][1]-pos)
        e1=norm(np.cross(u,[0,0,1] if abs(u[2])<.9 else [0,1,0])); e2=np.cross(u,e1)
        for k in range(3):
            phase=2*pi*k/3+.23*i
            w=-u/3+sqrt(8/9)*(cos(phase)*e1+sin(phase)*e2)
            h=add('H',pos+1.09*w); bond(i,h)
    elif len(ns)==2:
        for w in tetra_rest(atoms[ns[0]][1]-pos,atoms[ns[1]][1]-pos):
            h=add('H',pos+1.09*w); bond(i,h)
    else: raise ValueError('Unexpected carbon degree')
with open('initial.xyz','w') as f:
    f.write(str(len(atoms))+'\nNeutral trans-[Tc(SMe)2(dmpe)2], doublet (S=1/2)\n')
    for el,r in atoms: f.write(f'{el:2s} {r[0]: .9f} {r[1]: .9f} {r[2]: .9f}\n')
import json
json.dump({'bonds':bonds,'P':donors,'S':ss},open('connectivity.json','w'))
print('Atoms',len(atoms),'P donors',donors,'S donors',ss)
